write_file('apps/desktop/src/globe/weatherPresentationTexture.ts', "import type { AtmosphericWeatherPresentationArtifact, WeatherPresentationSystem } from '@world-forge/shared';\n\nexport type WeatherTextureMode = 'clouds' | 'weather';\n\ntype SphericalVector = { x: number; y: number; z: number };\ntype TangentFrame = {\n  direction: SphericalVector;\n  east: SphericalVector;\n  north: SphericalVector;\n  longitudeRad: number;\n  latitudeRad: number;\n};\ntype WindSample = {\n  tangent: SphericalVector;\n  zonal: number;\n  meridional: number;\n  speed: number;\n};\n\nconst STREAMER_OFFSETS = [-0.55, -0.3666667, -0.1833333, 0, 0.1833333, 0.3666667, 0.55] as const;\nconst STREAMER_WEIGHTS = [0.031, 0.11, 0.22, 0.278, 0.22, 0.11, 0.031] as const;\nconst seedHashCache = new Map<string, number>();\n\nexport function createWeatherPresentationTexture(\n  artifact: AtmosphericWeatherPresentationArtifact | null,\n  mode: WeatherTextureMode,\n  simulationDays: number\n): HTMLCanvasElement {\n  const canvas = document.createElement('canvas');\n  canvas.width = artifact?.payload.textureResolution.width ?? 512;\n  canvas.height = artifact?.payload.textureResolution.height ?? 256;\n  renderWeatherPresentationTexture(canvas, artifact, mode, simulationDays);\n  return canvas;\n}\n\nexport function renderWeatherPresentationTexture(\n  canvas: HTMLCanvasElement,\n  artifact: AtmosphericWeatherPresentationArtifact | null,\n  mode: WeatherTextureMode,\n  simulationDays: number\n): void {\n  const context = canvas.getContext('2d');\n  if (!context) return;\n  context.save();\n  context.clearRect(0, 0, canvas.width, canvas.height);\n  context.fillStyle = '#000000';\n  context.fillRect(0, 0, canvas.width, canvas.height);\n  if (!artifact) {\n    context.restore();\n    return;\n  }\n\n  context.globalCompositeOperation = 'lighter';\n  if (mode === 'clouds') drawWindOrientedCloudField(context, canvas, artifact, simulationDays);\n  for (const system of artifact.payload.systems) {\n    drawWeatherPresentationSystem(context, canvas, artifact.seed, system, mode, simulationDays);\n  }\n  context.restore();\n}\n\nfunction drawWindOrientedCloudField(\n  context: CanvasRenderingContext2D,\n  canvas: HTMLCanvasElement,\n  artifact: AtmosphericWeatherPresentationArtifact,\n  simulationDays: number\n): void {\n  const field = document.createElement('canvas');\n  field.width = canvas.width;\n  field.height = canvas.height;\n  const fieldContext = field.getContext('2d');\n  if (!fieldContext) return;\n  const image = fieldContext.createImageData(field.width, field.height);\n\n  for (let y = 0; y < field.height; y += 1) {\n    const v = (y + 0.5) / field.height;\n    for (let x = 0; x < field.width; x += 1) {\n      const u = (x + 0.5) / field.width;\n      const coverage = cloudCoverageSample(artifact, u, v, simulationDays);\n      const value = Math.round(Math.pow(coverage, 1.08) * 255);\n      const index = (y * field.width + x) * 4;\n      image.data[index] = value;\n      image.data[index + 1] = value;\n      image.data[index + 2] = value;\n      image.data[index + 3] = 255;\n    }\n  }\n  fieldContext.putImageData(image, 0, 0);\n\n  context.save();\n  context.imageSmoothingEnabled = true;\n  context.filter = 'blur(0.72px)';\n  context.globalAlpha = 1;\n  context.drawImage(field, 0, 0, canvas.width, canvas.height);\n  context.restore();\n}\n\nexport function cloudCoverageSample(\n  artifact: Pick<AtmosphericWeatherPresentationArtifact, 'seed' | 'payload'>,\n  u: number,\n  v: number,\n  simulationDays: number\n): number {\n  const frame = sphericalFrameFromUv(u, v);\n  const wind = sampleWindField(artifact, u, v, frame);\n  const travelRadians = -simulationDays * (0.006 + Math.min(1.5, wind.speed) * 0.025);\n  const advectedDirection = rotateDirectionAlongTangent(frame.direction, wind.tangent, travelRadians);\n  const advectedFrame = sphericalFrameFromDirection(advectedDirection);\n  const advectedWindTangent = projectOntoTangent(wind.tangent, advectedDirection, advectedFrame.east);\n\n  const bandEnvelope = cloudBandEnvelope(artifact, advectedFrame);\n  const broadSource = sphericalValueNoise(advectedDirection, 1.7, `${artifact.seed}:cloud-source`);\n  const streamer = windOrientedStreamerAtDirection(\n    advectedDirection,\n    advectedWindTangent,\n    `${artifact.seed}:streamer`\n  );\n  const cells = sphericalValueNoise(advectedDirection, 9.2, `${artifact.seed}:cells`);\n  const edgeBreakup = sphericalValueNoise(advectedDirection, 22, `${artifact.seed}:edge-breakup`);\n\n  const source = clamp01(bandEnvelope * 0.82 + broadSource * 0.48 - 0.18);\n  const formed = smoothStep(0.48 - source * 0.17, 0.72, streamer * 0.74 + cells * 0.26);\n  const breakup = smoothStep(0.39, 0.68, cells * 0.62 + edgeBreakup * 0.38);\n  const rawCoverage = clamp01(formed * (0.16 + breakup * 0.98) * (0.28 + source * 1.22));\n  return smoothStep(0.04, 0.62, rawCoverage);\n}\n\nexport function windOrientedStreamerSample(\n  artifact: Pick<AtmosphericWeatherPresentationArtifact, 'seed' | 'payload'>,\n  u: number,\n  v: number,\n  simulationDays = 0\n): number {\n  const frame = sphericalFrameFromUv(u, v);\n  const wind = sampleWindField(artifact, u, v, frame);\n  const travelRadians = -simulationDays * (0.006 + Math.min(1.5, wind.speed) * 0.025);\n  const advectedDirection = rotateDirectionAlongTangent(frame.direction, wind.tangent, travelRadians);\n  const advectedFrame = sphericalFrameFromDirection(advectedDirection);\n  const tangent = projectOntoTangent(wind.tangent, advectedDirection, advectedFrame.east);\n  return windOrientedStreamerAtDirection(advectedDirection, tangent, `${artifact.seed}:streamer`);\n}\n\nfunction cloudBandEnvelope(\n  artifact: Pick<AtmosphericWeatherPresentationArtifact, 'payload'>,\n  frame: TangentFrame\n): number {\n  const latitudeDeg = radiansToDegrees(frame.latitudeRad);\n  let envelope = 0;\n  for (const band of artifact.payload.cloudBands) {\n    const periodicWaveNumber = Math.max(1, Math.round(Math.abs(band.waveNumber)));\n    const centerLatitude = band.centerLatitudeDeg\n      + Math.sin(band.phaseRad + frame.longitudeRad * periodicWaveNumber) * band.waveAmplitudeDeg;\n    const halfWidth = Math.max(2, band.widthDeg * 0.62);\n    const normalizedDistance = (latitudeDeg - centerLatitude) / halfWidth;\n    envelope = Math.max(envelope, Math.exp(-0.5 * normalizedDistance * normalizedDistance) * band.density);\n  }\n  return envelope;\n}\n\nfunction sampleWindField(\n  artifact: Pick<AtmosphericWeatherPresentationArtifact, 'payload'>,\n  u: number,\n  v: number,\n  frame: TangentFrame\n): WindSample {\n  const field = artifact.payload.windField;\n  let zonal: number;\n  let meridional: number;\n\n  if (field && field.resolution.width > 0 && field.resolution.height > 0\n    && field.zonal.length === field.resolution.width * field.resolution.height\n    && field.meridional.length === field.resolution.width * field.resolution.height) {\n    zonal = bilinearPeriodicSample(field.zonal, field.resolution.width, field.resolution.height, u, v);\n    meridional = bilinearPeriodicSample(field.meridional, field.resolution.width, field.resolution.height, u, v);\n  } else {\n    zonal = artifact.payload.advection.zonalMeanDegPerDay / 18;\n    meridional = artifact.payload.advection.meridionalMeanDegPerDay / 5;\n  }\n\n  const tangentVector = addVectors(scaleVector(frame.east, zonal), scaleVector(frame.north, meridional));\n  const speed = vectorLength(tangentVector);\n  return {\n    tangent: speed > 0.000001 ? scaleVector(tangentVector, 1 / speed) : frame.east,\n    zonal,\n    meridional,\n    speed\n  };\n}\n\nfunction bilinearPeriodicSample(\n  values: readonly number[],\n  width: number,\n  height: number,\n  u: number,\n  v: number\n): number {\n  const x = wrapUnit(u) * width;\n  const xBase = Math.floor(x);\n  const x0 = wrapIndex(xBase, width);\n  const x1 = wrapIndex(xBase + 1, width);\n  const tx = x - xBase;\n  const y = clamp01(v) * Math.max(0, height - 1);\n  const y0 = Math.max(0, Math.min(height - 1, Math.floor(y)));\n  const y1 = Math.max(0, Math.min(height - 1, y0 + 1));\n  const ty = y - y0;\n  const a = finite(values[y0 * width + x0]);\n  const b = finite(values[y0 * width + x1]);\n  const c = finite(values[y1 * width + x0]);\n  const d = finite(values[y1 * width + x1]);\n  return linearInterpolate(linearInterpolate(a, b, tx), linearInterpolate(c, d, tx), ty);\n}\n\nfunction windOrientedStreamerAtDirection(\n  direction: SphericalVector,\n  tangent: SphericalVector,\n  seed: string\n): number {\n  let total = 0;\n  let weight = 0;\n  for (let index = 0; index < STREAMER_OFFSETS.length; index += 1) {\n    const sampleDirection = rotateDirectionAlongTangent(direction, tangent, STREAMER_OFFSETS[index]);\n    const sampleWeight = STREAMER_WEIGHTS[index];\n    total += sphericalValueNoise(sampleDirection, 4.4, seed) * sampleWeight;\n    weight += sampleWeight;\n  }\n  return weight > 0 ? total / weight : 0;\n}\n\nfunction sphericalValueNoise(direction: SphericalVector, frequency: number, seed: string): number {\n  const seedHash = hashSeed(seed);\n  const offsetX = seededUnit3(seedHash, 17, 31, 47) * 19.3;\n  const offsetY = seededUnit3(seedHash, 59, 71, 89) * 23.7;\n  const offsetZ = seededUnit3(seedHash, 101, 127, 149) * 17.9;\n  return smoothValueNoise3(\n    direction.x * frequency + offsetX,\n    direction.y * frequency + offsetY,\n    direction.z * frequency + offsetZ,\n    seedHash\n  );\n}\n\nfunction smoothValueNoise3(x: number, y: number, z: number, seedHash: number): number {\n  const x0 = Math.floor(x);\n  const y0 = Math.floor(y);\n  const z0 = Math.floor(z);\n  const fx = smoothStep(0, 1, x - x0);\n  const fy = smoothStep(0, 1, y - y0);\n  const fz = smoothStep(0, 1, z - z0);\n\n  const c000 = seededUnit3(seedHash, x0, y0, z0);\n  const c100 = seededUnit3(seedHash, x0 + 1, y0, z0);\n  const c010 = seededUnit3(seedHash, x0, y0 + 1, z0);\n  const c110 = seededUnit3(seedHash, x0 + 1, y0 + 1, z0);\n  const c001 = seededUnit3(seedHash, x0, y0, z0 + 1);\n  const c101 = seededUnit3(seedHash, x0 + 1, y0, z0 + 1);\n  const c011 = seededUnit3(seedHash, x0, y0 + 1, z0 + 1);\n  const c111 = seededUnit3(seedHash, x0 + 1, y0 + 1, z0 + 1);\n\n  const x00 = linearInterpolate(c000, c100, fx);\n  const x10 = linearInterpolate(c010, c110, fx);\n  const x01 = linearInterpolate(c001, c101, fx);\n  const x11 = linearInterpolate(c011, c111, fx);\n  return linearInterpolate(\n    linearInterpolate(x00, x10, fy),\n    linearInterpolate(x01, x11, fy),\n    fz\n  );\n}\n\nfunction sphericalFrameFromUv(u: number, v: number): TangentFrame {\n  const longitudeRad = wrapUnit(u) * Math.PI * 2 - Math.PI;\n  const latitudeRad = Math.PI / 2 - clamp01(v) * Math.PI;\n  const cosLatitude = Math.cos(latitudeRad);\n  return {\n    direction: normalizeVector({\n      x: cosLatitude * Math.cos(longitudeRad),\n      y: Math.sin(latitudeRad),\n      z: cosLatitude * Math.sin(longitudeRad)\n    }),\n    east: normalizeVector({ x: -Math.sin(longitudeRad), y: 0, z: Math.cos(longitudeRad) }),\n    north: normalizeVector({\n      x: -Math.sin(latitudeRad) * Math.cos(longitudeRad),\n      y: cosLatitude,\n      z: -Math.sin(latitudeRad) * Math.sin(longitudeRad)\n    }),\n    longitudeRad,\n    latitudeRad\n  };\n}\n\nfunction sphericalFrameFromDirection(direction: SphericalVector): TangentFrame {\n  const normalized = normalizeVector(direction);\n  const longitudeRad = Math.atan2(normalized.z, normalized.x);\n  const latitudeRad = Math.asin(Math.max(-1, Math.min(1, normalized.y)));\n  const cosLatitude = Math.cos(latitudeRad);\n  const fallbackEast = Math.abs(cosLatitude) < 0.000001 ? { x: 1, y: 0, z: 0 } : undefined;\n  return {\n    direction: normalized,\n    east: fallbackEast ?? normalizeVector({ x: -Math.sin(longitudeRad), y: 0, z: Math.cos(longitudeRad) }),\n    north: normalizeVector({\n      x: -Math.sin(latitudeRad) * Math.cos(longitudeRad),\n      y: cosLatitude,\n      z: -Math.sin(latitudeRad) * Math.sin(longitudeRad)\n    }),\n    longitudeRad,\n    latitudeRad\n  };\n}\n\nfunction rotateDirectionAlongTangent(\n  direction: SphericalVector,\n  tangent: SphericalVector,\n  radians: number\n): SphericalVector {\n  if (Math.abs(radians) < 0.00000001) return direction;\n  const normalizedDirection = normalizeVector(direction);\n  const normalizedTangent = projectOntoTangent(tangent, normalizedDirection, sphericalFrameFromDirection(normalizedDirection).east);\n  const axis = normalizeVector(crossVectors(normalizedDirection, normalizedTangent));\n  const cosAngle = Math.cos(radians);\n  const sinAngle = Math.sin(radians);\n  const axisCrossDirection = crossVectors(axis, normalizedDirection);\n  const axisDotDirection = dotVectors(axis, normalizedDirection);\n  return normalizeVector(addVectors(\n    addVectors(scaleVector(normalizedDirection, cosAngle), scaleVector(axisCrossDirection, sinAngle)),\n    scaleVector(axis, axisDotDirection * (1 - cosAngle))\n  ));\n}\n\nfunction projectOntoTangent(\n  vector: SphericalVector,\n  surfaceDirection: SphericalVector,\n  fallback: SphericalVector\n): SphericalVector {\n  const projected = addVectors(vector, scaleVector(surfaceDirection, -dotVectors(vector, surfaceDirection)));\n  const length = vectorLength(projected);\n  return length > 0.000001 ? scaleVector(projected, 1 / length) : fallback;\n}\n\nfunction drawWeatherPresentationSystem(\n  context: CanvasRenderingContext2D,\n  canvas: HTMLCanvasElement,\n  seed: string,\n  system: WeatherPresentationSystem,\n  mode: WeatherTextureMode,\n  simulationDays: number\n): void {\n  const longitudeDeg = wrapSignedDegrees(system.longitudeDeg + system.driftEastDegPerDay * simulationDays);\n  const latitudeDeg = Math.max(-88, Math.min(88, system.latitudeDeg + Math.sin(system.phaseRad + simulationDays * 0.08) * system.driftNorthDegPerDay));\n  const x = (longitudeDeg + 180) / 360 * canvas.width;\n  const y = (90 - latitudeDeg) / 180 * canvas.height;\n  const radius = Math.max(3, system.radiusDeg / 360 * canvas.width);\n  const density = clamp01(system.density);\n  const rotation = system.phaseRad + system.spinRadiansPerDay * simulationDays;\n  const puffCount = system.kind === 'cyclone' ? 34 : system.kind === 'front' ? 28 : 22;\n\n  for (const offset of [-canvas.width, 0, canvas.width]) {\n    const cx = x + offset;\n    context.save();\n    context.filter = mode === 'weather' ? 'blur(0.65px)' : 'blur(0.9px)';\n    for (let index = 0; index < puffCount; index += 1) {\n      const t = puffCount <= 1 ? 0 : index / (puffCount - 1);\n      const angleNoise = (seededUnit(`${seed}:${system.id}:angle`, index, 0) - 0.5) * 0.9;\n      const radialNoise = seededUnit(`${seed}:${system.id}:radius`, index, 1);\n      const sizeNoise = seededUnit(`${seed}:${system.id}:size`, index, 2);\n      let px: number;\n      let py: number;\n\n      if (system.kind === 'front') {\n        const along = (t - 0.5) * radius * 1.9;\n        const curve = Math.sin(t * Math.PI * 2 + rotation) * radius * 0.22;\n        px = cx + Math.cos(rotation) * along - Math.sin(rotation) * curve;\n        py = y + (Math.sin(rotation) * along + Math.cos(rotation) * curve) * 0.58;\n      } else {\n        const turns = system.kind === 'cyclone' ? 2.55 : 1.15;\n        const angle = rotation + t * Math.PI * 2 * turns + angleNoise;\n        const distance = radius * (0.08 + Math.pow(t, 0.72) * 0.86) * (0.82 + radialNoise * 0.25);\n        px = cx + Math.cos(angle) * distance;\n        py = y + Math.sin(angle) * distance * 0.62;\n      }\n\n      const puffRadius = radius * (0.07 + sizeNoise * (mode === 'weather' ? 0.17 : 0.22));\n      const strength = clamp01((0.34 + density * 0.72) * (0.72 + radialNoise * 0.36));\n      drawSoftPuff(context, px, py, puffRadius, strength, system.kind === 'front' ? 1.75 : 1);\n    }\n    context.restore();\n  }\n}\n\nfunction drawSoftPuff(\n  context: CanvasRenderingContext2D,\n  x: number,\n  y: number,\n  radius: number,\n  strength: number,\n  stretchX: number\n): void {\n  context.save();\n  context.translate(x, y);\n  context.scale(stretchX, 1);\n  const gradient = context.createRadialGradient(0, 0, radius * 0.08, 0, 0, radius);\n  const core = Math.round(150 + clamp01(strength) * 105);\n  gradient.addColorStop(0, `rgba(${core}, ${core}, ${core}, ${0.45 + strength * 0.45})`);\n  gradient.addColorStop(0.48, `rgba(${Math.round(core * 0.82)}, ${Math.round(core * 0.82)}, ${Math.round(core * 0.82)}, ${0.22 + strength * 0.34})`);\n  gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');\n  context.fillStyle = gradient;\n  context.beginPath();\n  context.arc(0, 0, radius, 0, Math.PI * 2);\n  context.fill();\n  context.restore();\n}\n\n// Projected surface and debug textures still use this helper. The Cycle 2.2 cloud\n// field is intrinsically spherical and never calls it.\nexport function normalizeHorizontalTextureSeam(canvas: HTMLCanvasElement, columns = 2): void {\n  const context = canvas.getContext('2d', { willReadFrequently: true });\n  if (!context || canvas.width < 2 || canvas.height < 1) return;\n  const width = canvas.width;\n  const height = canvas.height;\n  const seamColumns = Math.max(1, Math.min(columns, Math.floor(width / 2)));\n  const image = context.getImageData(0, 0, width, height);\n  for (let y = 0; y < height; y += 1) {\n    for (let offset = 0; offset < seamColumns; offset += 1) {\n      const left = (y * width + offset) * 4;\n      const right = (y * width + (width - 1 - offset)) * 4;\n      for (let channel = 0; channel < 4; channel += 1) {\n        const value = Math.round((image.data[left + channel] + image.data[right + channel]) / 2);\n        image.data[left + channel] = value;\n        image.data[right + channel] = value;\n      }\n    }\n  }\n  context.putImageData(image, 0, 0);\n}\n\nfunction hashSeed(seed: string): number {\n  const cached = seedHashCache.get(seed);\n  if (cached !== undefined) return cached;\n  let hash = 2166136261;\n  for (let index = 0; index < seed.length; index += 1) hash = Math.imul(hash ^ seed.charCodeAt(index), 16777619);\n  const normalized = hash >>> 0;\n  seedHashCache.set(seed, normalized);\n  return normalized;\n}\n\nfunction seededUnit3(seedHash: number, x: number, y: number, z: number): number {\n  let hash = seedHash;\n  hash ^= Math.imul(x + 374761393, 668265263);\n  hash ^= Math.imul(y + 2246822519, 3266489917);\n  hash ^= Math.imul(z + 3266489917, 374761393);\n  hash = Math.imul(hash ^ (hash >>> 15), 2246822507);\n  return ((hash ^ (hash >>> 13)) >>> 0) / 4294967295;\n}\n\nfunction seededUnit(seed: string, x: number, y: number): number {\n  return seededUnit3(hashSeed(seed), x, y, x ^ y);\n}\n\nfunction smoothStep(edge0: number, edge1: number, value: number): number {\n  const span = edge1 - edge0;\n  if (Math.abs(span) < 0.000001) return value >= edge1 ? 1 : 0;\n  const t = clamp01((value - edge0) / span);\n  return t * t * (3 - 2 * t);\n}\n\nfunction linearInterpolate(a: number, b: number, t: number): number {\n  return a + (b - a) * t;\n}\n\nfunction dotVectors(a: SphericalVector, b: SphericalVector): number {\n  return a.x * b.x + a.y * b.y + a.z * b.z;\n}\n\nfunction crossVectors(a: SphericalVector, b: SphericalVector): SphericalVector {\n  return {\n    x: a.y * b.z - a.z * b.y,\n    y: a.z * b.x - a.x * b.z,\n    z: a.x * b.y - a.y * b.x\n  };\n}\n\nfunction addVectors(a: SphericalVector, b: SphericalVector): SphericalVector {\n  return { x: a.x + b.x, y: a.y + b.y, z: a.z + b.z };\n}\n\nfunction scaleVector(vector: SphericalVector, scale: number): SphericalVector {\n  return { x: vector.x * scale, y: vector.y * scale, z: vector.z * scale };\n}\n\nfunction vectorLength(vector: SphericalVector): number {\n  return Math.sqrt(dotVectors(vector, vector));\n}\n\nfunction normalizeVector(vector: SphericalVector): SphericalVector {\n  const length = vectorLength(vector);\n  return length > 0.000001 ? scaleVector(vector, 1 / length) : { x: 1, y: 0, z: 0 };\n}\n\nfunction radiansToDegrees(value: number): number {\n  return value * 180 / Math.PI;\n}\n\nfunction wrapIndex(value: number, size: number): number {\n  return ((value % size) + size) % size;\n}\n\nfunction wrapUnit(value: number): number {\n  return ((value % 1) + 1) % 1;\n}\n\nfunction wrapSignedDegrees(value: number): number {\n  return ((value + 180) % 360 + 360) % 360 - 180;\n}\n\nfunction finite(value: number | undefined, fallback = 0): number {\n  return Number.isFinite(value) ? value as number : fallback;\n}\n\nfunction clamp01(value: number): number {\n  return Math.max(0, Math.min(1, value));\n}\n")
write_file('apps/desktop/src/globe/weatherPresentationTexture.test.ts', "import { describe, expect, it } from 'vitest';\nimport type { AtmosphericWeatherPresentationArtifact } from '@world-forge/shared';\nimport { cloudCoverageSample, windOrientedStreamerSample } from './weatherPresentationTexture';\n\nfunction createArtifact(wind: 'east' | 'north' | 'varied' = 'varied'): AtmosphericWeatherPresentationArtifact {\n  const width = 16;\n  const height = 8;\n  const zonal: number[] = [];\n  const meridional: number[] = [];\n  for (let y = 0; y < height; y += 1) {\n    for (let x = 0; x < width; x += 1) {\n      if (wind === 'east') {\n        zonal.push(0.85);\n        meridional.push(0);\n      } else if (wind === 'north') {\n        zonal.push(0);\n        meridional.push(0.85);\n      } else {\n        const latitude = Math.PI / 2 - ((y + 0.5) / height) * Math.PI;\n        zonal.push(Math.sin(latitude * 2) * 0.62);\n        meridional.push(Math.cos((x / width) * Math.PI * 2) * 0.22);\n      }\n    }\n  }\n\n  return {\n    seed: 'weather-qa-seed',\n    payload: {\n      textureResolution: { width: 512, height: 256 },\n      meanCloudCover: 0.46,\n      cloudBands: [\n        { id: 'north', centerLatitudeDeg: 42, widthDeg: 18, density: 0.72, phaseRad: 0.4, waveNumber: 2, waveAmplitudeDeg: 7, driftDegPerDay: 0.8 },\n        { id: 'equator', centerLatitudeDeg: 2, widthDeg: 22, density: 0.84, phaseRad: 1.1, waveNumber: 2, waveAmplitudeDeg: 5, driftDegPerDay: 1.25 },\n        { id: 'south', centerLatitudeDeg: -46, widthDeg: 16, density: 0.66, phaseRad: 2.4, waveNumber: 3, waveAmplitudeDeg: 8, driftDegPerDay: 0.65 }\n      ],\n      systems: [],\n      advection: { zonalMeanDegPerDay: 5, meridionalMeanDegPerDay: 0.2 },\n      windField: {\n        resolution: { width, height },\n        zonal,\n        meridional\n      }\n    }\n  } as AtmosphericWeatherPresentationArtifact;\n}\n\ndescribe('wind-oriented spherical cloud presentation', () => {\n  it('is deterministic for the same spherical location, flow field, and time', () => {\n    const artifact = createArtifact();\n    expect(cloudCoverageSample(artifact, 0.33, 0.44, 12.5)).toBe(cloudCoverageSample(artifact, 0.33, 0.44, 12.5));\n    expect(windOrientedStreamerSample(artifact, 0.33, 0.44, 12.5)).toBe(windOrientedStreamerSample(artifact, 0.33, 0.44, 12.5));\n  });\n\n  it('elongates streamer variation along the generated prevailing wind', () => {\n    const artifact = createArtifact('east');\n    const angularStep = 0.026;\n    const alongStepU = angularStep / (Math.PI * 2);\n    const acrossStepV = angularStep / Math.PI;\n    let alongVariation = 0;\n    let acrossVariation = 0;\n    let samples = 0;\n\n    for (let row = 0; row < 9; row += 1) {\n      const v = 0.36 + row * 0.035;\n      for (let column = 0; column < 40; column += 1) {\n        const u = 0.08 + column * 0.021;\n        const base = windOrientedStreamerSample(artifact, u, v, 3);\n        alongVariation += Math.abs(base - windOrientedStreamerSample(artifact, u + alongStepU, v, 3));\n        acrossVariation += Math.abs(base - windOrientedStreamerSample(artifact, u, v + acrossStepV, 3));\n        samples += 1;\n      }\n    }\n\n    expect(alongVariation / samples).toBeLessThan((acrossVariation / samples) * 0.72);\n  });\n\n  it('preserves clear-sky gaps instead of producing a continuous haze', () => {\n    const artifact = createArtifact();\n    const samples = Array.from({ length: 2048 }, (_, index) => {\n      const x = index % 64;\n      const y = Math.floor(index / 64);\n      return cloudCoverageSample(artifact, (x + 0.5) / 64, (y + 0.5) / 32, 4);\n    });\n    const clearSkyShare = samples.filter((value) => value < 0.02).length / samples.length;\n    const denseCloudShare = samples.filter((value) => value > 0.35).length / samples.length;\n    const mean = samples.reduce((sum, value) => sum + value, 0) / samples.length;\n    expect(clearSkyShare).toBeGreaterThan(0.55);\n    expect(denseCloudShare).toBeGreaterThan(0.03);\n    expect(mean).toBeLessThan(0.2);\n  });\n\n  it('is intrinsically continuous across the former longitude seam', () => {\n    const artifact = createArtifact();\n    for (let index = 0; index < 24; index += 1) {\n      const v = (index + 0.5) / 24;\n      const left = cloudCoverageSample(artifact, 0.000001, v, 7.25);\n      const right = cloudCoverageSample(artifact, 0.999999, v, 7.25);\n      expect(Math.abs(left - right)).toBeLessThan(0.002);\n    }\n  });\n\n  it('advects with local flow over shared simulation time', () => {\n    const artifact = createArtifact();\n    const before = Array.from({ length: 64 }, (_, index) => cloudCoverageSample(artifact, (index + 0.5) / 64, 0.36, 0));\n    const after = Array.from({ length: 64 }, (_, index) => cloudCoverageSample(artifact, (index + 0.5) / 64, 0.36, 18));\n    const change = before.reduce((sum, value, index) => sum + Math.abs(value - after[index]), 0) / before.length;\n    expect(change).toBeGreaterThan(0.015);\n  });\n});\n")
write_file('refs/handoffs/system-visualization-enrichment.md', "# System Visualization and Enrichment Handoff\n\nUpdated: 2026-07-31\n\nStatus: Visualizer Cycle 2.2 wind-oriented spherical clouds validated; System Explore is next\n\nPlanning source: `refs/planning/pi-system-visualization-and-progressive-body-enrichment.md`\n\nTracking issue: #35\n\n## Delivered foundation\n\n- Versioned project-enrichment workflow contract.\n- Inspectable `project.system-orbital-context@1.0.0` graph.\n- Deterministic orbital presentation payload and artifact signature.\n- Lazy first-Globe execution outside ordinary generation.\n- Visible running, completed, stale, cancelled, and failed UI state.\n- Optional artifacts attached to `WorldProject.enrichmentArtifacts` and carried by normal project save and export serialization.\n- Graph-node editor selection and completed-node timing for enrichment workflows.\n\n## Visualizer Cycle 1 living globe\n\n- Shared simulation clock with play, pause, speed, reset, day-of-year, and time-of-day controls.\n- Deterministic procedural star background and generated star/light coupling.\n- Clock-derived physical planetary spin and generated axial tilt.\n- Deterministic moon traversal and nearby visible-body motion.\n- Camera yaw and pitch orbit around the fixed physical system.\n- Pointer hold pauses the shared clock; release restores the prior play state.\n- Bounded soft-shadow proof for moons and the primary globe.\n- Wireframe placeholder treatment and deliberately compressed illustrative local-system scale.\n\n## Visualizer Cycle 2 clouds and weather\n\n- Added inspectable `project.atmospheric-weather-presentation` with six instrumented nodes:\n  - read generated climate fields;\n  - resolve climatological cloud bands;\n  - seed fronts, cyclones, and convective systems;\n  - resolve bounded atmospheric advection;\n  - validate the presentation model;\n  - package and persist the artifact.\n- The workflow runs only after Clouds or Weather systems is first enabled in Globe view and current orbital context exists.\n- Existing moisture, precipitation, wind, water, temperature, elevation, and terrain data are consumed without rerunning climate generation.\n- The artifact declares `weatherAuthority: illustrative`; it is scientifically informed presentation, not authoritative meteorological history.\n- Globe view provides separate Clouds and Weather systems toggles.\n- Weather-system puffs remain close to the cloud deck, advance on the shared clock, and preserve the accepted larger coherent forms.\n- Cloud and weather alpha shells remain excluded from the current shadow-caster path. Moons remain the bounded local-system shadow proof.\n- The 35% and 50% local-system zoom stops remain available.\n\n## Visualizer Cycle 2.2 final cloud renderer boundary\n\n- The weather workflow is versioned at `project.atmospheric-weather-presentation@1.1.0`.\n- The artifact now persists a compact deterministic wind field downsampled from the generated `windX` and `windY` layers.\n- Cloud sampling converts each texture sample to a globe-space surface direction and local east/north tangent basis.\n- The local generated wind vector determines streamer orientation and shared-clock backtraced advection.\n- Cloud structure combines:\n  - a broad climatological moisture/source envelope;\n  - a long wind-oriented streamer layer;\n  - smaller broken cell structure;\n  - high-frequency edge breakup for soft, irregular margins.\n- Clear sky remains the dominant background. The renderer does not create a low-opacity planetary haze.\n- The cloud field is intrinsically continuous in globe space. It is rasterized to an equirectangular canvas only as a Three.js texture transport, and the cloud path does not average or blur the first and last texture columns.\n- Existing projected surface/debug textures may still use their separate seam-normalization helper; that helper is not part of cloud generation.\n- Renderer diagnostics identify `wind-oriented-spherical-v4`, `thin-streamers-clear-sky`, and `spherical-continuous`.\n- Focused contracts cover deterministic sampling, directional anisotropy, clear-sky share, cross-seam continuity, and time evolution.\n\n## Current boundaries\n\n- No precipitation, lightning, or authoritative forecast/history simulation.\n- No soft transmittance-based cloud shadows.\n- No seasonal surface response yet.\n- No full `System` Explore mode yet.\n- No secondary-body generation.\n- No N-body simulation or authoritative ephemeris.\n- Clock-panel mobility/collapse remains a backlog item.\n- The primary generation graph, deterministic world signature, and replay contract remain unchanged.\n- Geographic drilldown issue #10 remains pinned and outside this PI slice.\n\n## Next increment\n\nAdd the bounded full `System` Explore mode in a dedicated `SystemViewer`:\n\n- add `Map | Globe | System`;\n- show the generated star, primary world, moons, planets, and other scaffold bodies;\n- share the existing simulation clock;\n- support body selection, focus, return to primary, optional orbit paths, and optional labels;\n- distinguish placeholder and generated styling;\n- provide compressed overview and relative-distance modes where practical;\n- provide a body inspector with basic scaffold values and generation status.\n\nDo not begin secondary-body generation in the same slice. Body lifecycle/queue and the airless-moon proof follow after the viewer and selection surface are established.\n")
write_file('refs/testing/atmospheric-weather-visual-qa.md', "# Atmospheric Weather Visual QA\n\nUpdated: 2026-07-31\n\n## Cycle 2.2 acceptance path\n\n1. Generate the fast 256 x 128 world.\n2. Open Globe view and enable Clouds, then Weather systems.\n3. Confirm the lazy atmospheric-weather workflow completes as `project.atmospheric-weather-presentation@1.1.0`.\n4. Confirm clouds form thin, long, narrow, broken streamers aligned with changing prevailing wind directions rather than round isotropic blobs or broad painted latitude bands.\n5. Confirm cloud edges are very soft and poorly defined, with smaller broken puffs and many genuinely clear-sky gaps.\n6. Confirm there is no low-opacity planetary haze when looking across the full illuminated globe.\n7. Advance the shared clock and confirm local cloud structures advect with the flow field while the larger weather systems continue their accepted coherent motion.\n8. Orbit the camera through the former longitude wrap location and inspect both daylight and nightside views. Confirm no sharp vertical seam, repeated edge, or flat-map-wrap impression appears.\n9. Confirm weather systems remain close to the cloud deck, read as larger embedded features, and retain their existing soft front/cyclone/convective presentation.\n10. Set Globe zoom to 35% and 50% and confirm the accepted local-system framing and primary-moon visibility remain intact.\n11. Confirm cloud and weather shells do not cast the rejected oversized hard alpha-map shadow bands.\n12. Confirm moon positions and the directional stellar light vector still update under the shared clock.\n13. Verify 1440 x 900 and 1920 x 1080 without page-level overflow or browser errors.\n\n## Automated contracts\n\nThe focused cloud suite must verify:\n\n- deterministic spherical and wind-oriented sampling;\n- lower variation along the wind direction than across it;\n- dominant clear-sky share with a nonzero dense-cloud share and low mean background coverage;\n- intrinsic continuity across the former longitude seam;\n- visible time evolution under local-flow advection.\n\nThe weather-enrichment suite must verify that the compact wind field is deterministic, finite, correctly sized, and derived into the persisted presentation artifact.\n\n## Final renderer boundary\n\nClouds use globe-space procedural sampling. Each raster pixel is converted to a unit surface direction and local tangent frame before the generated wind field, source envelope, streamer, cell, and edge layers are evaluated. The resulting canvas remains equirectangular only because Three.js consumes it as a texture.\n\nThe cloud path does not repair a discontinuous texture by averaging or blurring its first and last columns. Cross-seam continuity comes from sampling the same sphere direction and periodic wind field on both sides of the wrap.\n\nProjected surface and debug textures retain their separate seam-normalization helper. That legacy helper is not used by the Cycle 2.2 cloud renderer.\n\nCloud shadows remain intentionally disabled until a soft transmittance-based implementation exists. The current proof isolates moon-shadow geometry instead of allowing an alpha-tested shell to impersonate a planetary-scale Venetian blind.\n")

